package main

import (
	"fmt"
	"math"
)

func main() {
	var n, k int64
	fmt.Scan(&n, &k)

	if n == 1 {
		fmt.Println(0)
		return
	}

	// Max pipes achievable
	maxPipes := 1 + k*(k-1)/2
	if n > maxPipes {
		fmt.Println(-1)
		return
	}

	// Min pipes achievable with m splitters: 1 + sum_{i=2}^{m+1} i = 1 + (m+1)(m+2)/2 - 1 = (m+1)(m+2)/2
	// Actually min pipes with m splitters using smallest splitters {2, 3, ..., m+1}:
	// Net gain per splitter i is (i-1). Sum of (i-1) for i=2 to m+1 is sum_{j=1}^m j = m(m+1)/2.
	// Total pipes = 1 + m(m+1)/2.

	lo := int64(1)
	hi := k - 1
	ans := int64(-1)

	for lo <= hi {
		mid := (lo + hi) / 2
		// Max pipes with mid splitters: use largest mid splitters {k-mid+1, ..., k}
		// Sum of outputs = sum_{i=k-mid+1}^k i = mid*(2*k - mid + 1)/2
		// Net gain = Sum outputs - mid = mid*(2*k - mid + 1)/2 - mid = mid*(2*k - mid - 1)/2
		// Total pipes = 1 + mid*(2*k - mid - 1)/2
		// Check overflow: mid, k up to 1e9. mid*k up to 1e18. Fits in int64.
		maxWithMid := 1 + mid*(2*k-mid-1)/2

		// Min pipes with mid splitters: use smallest mid splitters {2, ..., mid+1}
		// Net gain = sum_{i=2}^{mid+1} (i-1) = sum_{j=1}^{mid} j = mid*(mid+1)/2
		// Total pipes = 1 + mid*(mid+1)/2
		minWithMid := 1 + mid*(mid+1)/2

		if n > maxWithMid {
			lo = mid + 1
		} else if n < minWithMid {
			hi = mid - 1
		} else {
			ans = mid
			hi = mid - 1
		}
	}

	fmt.Println(ans)
}
